+// Human conversation annotations. Never promote excerpts, quotes or emoji to provenance.
+const HUMAN_CONTENT_LABEL = "human_message_not_provenance";
+const excerpt = (value) => typeof value === "string" ? Array.from(value).slice(0, 512).join("") : null;
+
+export function parseContextJson(value) {
+  try { return JSON.parse(value || "{}") || {}; } catch { return {}; }
+}
+
+export function telegramReplyContext(message) {
+  const target = message.reply_to_message;
+  if (!target || !Number.isSafeInteger(target.message_id) || target.message_id <= 0) return null;
+  return {
+    telegram_message_id: target.message_id,
+    excerpt: excerpt(target.text || target.caption),
+    ...(message.quote ? {
+      quote: {
+        text: excerpt(message.quote.text),
+        position: message.quote.position ?? null,
+        is_manual: message.quote.is_manual === true,
+      },
+    } : {}),
+  };
+}
+
+// A Telegram message ID is chat-scoped, not bot-scoped. Resolve across the
+// agents in this chat; reads are scoped to an authorized chat by the caller.
+// Resolve again on reads so an event preceding its delivery receipt is retained.
+export function resolveTelegramTarget(db, chatId, messageId) {
+  if (!Number.isSafeInteger(messageId) || messageId <= 0) return {};
+  const inbound = db.prepare(`SELECT id FROM inbound_queue WHERE channel='telegram'
+    AND telegram_chat_id=? AND telegram_message_id=?
+    ORDER BY id DESC LIMIT 1`).get(String(chatId), messageId);
+  if (inbound) return { inbound_id: inbound.id };
+  const outbound = db.prepare(`SELECT id FROM outbox_items WHERE channel='telegram' AND target=?
+    AND telegram_message_id=?
+    ORDER BY created_at DESC LIMIT 1`).get(String(chatId), messageId);
+  if (outbound) return { outbound_id: outbound.id };
+  const chunk = db.prepare(`SELECT inbound_id, sequence_number FROM drainer_reply_deliveries
+    WHERE target=? AND message_id=? AND state='confirmed'
+    ORDER BY updated_at DESC LIMIT 1`).get(String(chatId), messageId);
+  return chunk ? { journal_id: `jr:${chunk.inbound_id}:${chunk.sequence_number}` } : {};
+}
+
+// Call only after authenticating both ingress and operator identity. No queue
+// row is created: reaction-only updates must not trigger commands or a turn.
+export function recordOperatorReaction(db, parsed) {
+  db.prepare(`INSERT OR IGNORE INTO operator_reactions
+    (chat_id, message_id, actor_id, event_date, old_reactions_json, new_reactions_json)
+    VALUES (?, ?, ?, ?, ?, ?)`).run(
+      parsed.chatId, parsed.messageId, parsed.senderId, parsed.date,
+      JSON.stringify(parsed.reaction.old), JSON.stringify(parsed.reaction.new),
+    );
+}
+
+export function readOperatorReactions(db, chatId, messageId = null, limit = 50) {
+  if (messageId !== null && (!Number.isSafeInteger(messageId) || messageId <= 0)) return [];
+  return db.prepare(`SELECT * FROM operator_reactions WHERE chat_id=? ${messageId === null ? "" : "AND message_id=?"}
+    ORDER BY event_date DESC, id DESC LIMIT ?`)
+    .all(String(chatId), ...(messageId === null ? [] : [messageId]), limit)
+    .map((row) => {
+      const old = parseContextJson(row.old_reactions_json);
+      const current = parseContextJson(row.new_reactions_json);
+      const has = (items, item) => items.some((other) => JSON.stringify(other) === JSON.stringify(item));
+      return {
+        label: HUMAN_CONTENT_LABEL,
+        telegram_message_id: row.message_id,
+        ...resolveTelegramTarget(db, chatId, row.message_id),
+        actor: { id: row.actor_id },
+        timestamp: new Date(row.event_date * 1000).toISOString(),
+        added: current.filter((item) => !has(old, item)),
+        removed: old.filter((item) => !has(current, item)),
+        current,
+      };
+    });
+}
+
+export function inboundMessageContext(db, row) {
+  if (row.channel !== "telegram") return {};
+  const json = parseContextJson(row.message_json);
+  const chatId = json.chatId ?? json.raw?.chat?.id ?? row.sender_id;
+  const reply = json.reply_to ?? telegramReplyContext(json.raw || json);
+  const messageId = json.messageId ?? json.message_id ?? null;
+  return {
+    ...(reply ? {
+      reply_to: {
+        ...reply,
+        ...resolveTelegramTarget(db, chatId, reply.telegram_message_id),
+        label: HUMAN_CONTENT_LABEL,
+      },
+    } : {}),
+    reactions: messageId === null ? [] : readOperatorReactions(db, chatId, messageId),
+  };
+}
+
+// Seek to the next chat in the covering index instead of visiting every
+// historical inbound row to DISTINCT its JSON. Work scales with chat count.
+export function agentTelegramChats(db, agentId) {
+  const first = db.prepare(`SELECT telegram_chat_id AS chat FROM inbound_queue
+    WHERE agent_id=? AND channel='telegram' AND telegram_chat_id IS NOT NULL
+    ORDER BY telegram_chat_id LIMIT 1`);
+  const next = db.prepare(`SELECT telegram_chat_id AS chat FROM inbound_queue
+    WHERE agent_id=? AND channel='telegram' AND telegram_chat_id>?
+    ORDER BY telegram_chat_id LIMIT 1`);
+  const chats = [];
+  let row = first.get(agentId);
+  while (row) {
+    chats.push(row.chat);
+    row = next.get(agentId, row.chat);
+  }
+  return chats;
+}
+
+export function inboundReactionContext(db, row) {
+  if (row.channel !== 'telegram') return [];
+  const json = parseContextJson(row.message_json);
+  return readOperatorReactions(db, json.chatId ?? json.raw?.chat?.id ?? row.sender_id);
+}

